   232→		StartedAt:             now,
   233→		LastInteractionAt:     &now,
   234→		CheckpointCount:       0,
   235→>>>>>>> origin/main
   236→		UntrackedFilesAtStart: untrackedFiles,
   237→		AgentType:             agentType,
   238→		TranscriptPath:        transcriptPath,
   239→		FirstPrompt:           truncatePromptForStorage(userPrompt),
   240→	}
   241→
   242→	if err := s.saveSessionState(state); err != nil {
   243→		return nil, err
